INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'inflazione-potere-acquisto-perche-il-capitale-deve-crescere',
    'Inflazione e potere d''acquisto: perché tenere i soldi fermi ha un costo nascosto',
    'Un capitale che non cresce almeno quanto l''inflazione perde valore reale ogni anno, anche se il numero sul conto resta identico.',
    'Come l''inflazione erode il potere d''acquisto di un capitale fermo nel tempo, e la differenza tra rendimento nominale e rendimento reale spiegata con esempi.',
    'pianificazione',
    '📉',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un capitale che non cresce almeno quanto l''inflazione non sta davvero “stando fermo”: sta perdendo potere d''acquisto ogni anno, anche se il numero sul conto resta identico. È uno degli errori di percezione più comuni in finanza personale.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Un esempio concreto</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con un''inflazione media del 2,5% annuo, 10.000&euro; tenuti fermi su un conto che non matura interessi valgono, in termini di potere d''acquisto reale, circa 7.800&euro; dopo 10 anni e circa 6.100&euro; dopo 20 anni. Il numero sul conto non è cambiato: è cambiato quanto puoi comprarci.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché la liquidità ferma ha un costo nascosto</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Tenere un fondo di emergenza liquido è corretto e necessario (ne parliamo in dettaglio più avanti), ma tenere fermo per anni un capitale ben oltre quella soglia di sicurezza ha un costo reale, anche se invisibile: quel denaro non genera nulla e perde silenziosamente valore reale ogni anno che passa.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Rendimento nominale vs rendimento reale</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un investimento che rende il 3% annuo con un''inflazione al 2,5% ha un <strong>rendimento reale</strong> di solo lo 0,5% — la differenza tra rendimento nominale (quello che vedi) e inflazione (quello che perdi comunque) è il numero che conta davvero per sapere se il tuo capitale sta crescendo o solo restando a galla.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Calcola l''effetto sul tuo capitale</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con il <a href="/calcolatore-inflazione.php" class="text-accent hover:underline font-medium">calcolatore di inflazione e potere d’acquisto</a> puoi vedere quanto varrà davvero una somma tra qualche anno, al netto dell’inflazione attesa. Lo stesso principio vale per l’<a href="/calcolatore-interesse-composto.php" class="text-accent hover:underline font-medium">interesse composto</a>: un rendimento che batte l''inflazione nel tempo è ciò che fa la reale differenza tra risparmiare e investire.</p>',
    'pubblicato',
    '2026-07-18 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'patrimonio-netto-cos-e-perche-seguirlo-nel-tempo',
    'Patrimonio netto: cos''è e perché seguirlo nel tempo conta più del reddito',
    'Il reddito racconta quanto guadagni oggi. Il patrimonio netto racconta il risultato cumulato di anni di decisioni: perché vale la pena seguirlo nel tempo.',
    'Cos''è il patrimonio netto, come si calcola (attività meno passività) e perché seguirlo nel tempo è più utile che guardarlo una volta sola.',
    'pianificazione',
    '📊',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il reddito mensile è il numero che guardiamo più spesso, ma non è quello che determina la nostra sicurezza finanziaria nel tempo. Quel numero è il <strong>patrimonio netto</strong>: tutto quello che possiedi meno tutto quello che devi.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come si calcola</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Si sommano tutte le <strong>attività</strong> (conti, investimenti, immobili, eventuali altri beni di valore) e si sottraggono tutte le <strong>passività</strong> (debito residuo del mutuo, prestiti, carte di credito revolving). Il risultato può essere sorprendente in entrambe le direzioni: due persone con lo stesso stipendio possono avere patrimoni netti molto diversi in base a quanto debito portano e quanto hanno accumulato.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché seguirlo nel tempo conta più del reddito</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il reddito racconta quanto guadagni oggi. Il patrimonio netto racconta il risultato cumulato di anni di decisioni: quanto hai risparmiato, come hai investito, quanto debito hai ridotto. Seguirlo trimestre dopo trimestre, invece che come un numero isolato, rivela una traiettoria — sta crescendo? A che ritmo? — che il solo stipendio non mostra mai.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Un errore comune: guardarlo una volta sola</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Calcolare il patrimonio netto una tantum dice poco. Il valore reale sta nel confronto nel tempo: un patrimonio netto che cresce del 10% l''anno racconta una storia molto diversa da uno che resta piatto, anche se il numero di partenza fosse identico.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Vedi il tuo, aggiornato automaticamente</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Puoi calcolare un primo istantanea con il <a href="/calcolatore-patrimonio-netto.php" class="text-accent hover:underline font-medium">calcolatore di patrimonio netto</a> — <a href="/analisi.php" class="text-accent hover:underline font-medium">su Reflexi</a> invece il patrimonio netto si aggiorna da solo ogni volta che registri una transazione, un investimento o una rata di mutuo, perché nasce dall''incrocio automatico di conti, investimenti e debiti residui reali, non da un calcolo manuale rifatto ogni volta.</p>',
    'pubblicato',
    '2026-07-21 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'pensione-integrativa-fondo-pensione-quanto-serve',
    'Pensione integrativa: quanto serve davvero e da quando iniziare',
    'Perché la previdenza integrativa non è più un''opzione per pochi, quanto conta iniziare presto, e come scegliere tra fondo pensione e investimento autonomo.',
    'Quanto capitale serve per una pensione integrativa adeguata, perché iniziare presto conta, e le differenze tra fondo pensione negoziale e investimento autonomo.',
    'pianificazione',
    '👴',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">La pensione pubblica obbligatoria, per chi lavora oggi in Italia, sarà quasi certamente più bassa in proporzione all''ultimo stipendio rispetto a quella di chi è andato in pensione trent''anni fa — è il motivo per cui la previdenza integrativa è passata da opzione per pochi a considerazione rilevante per la maggior parte di chi pianifica seriamente il proprio futuro.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché il divario si è allargato</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il sistema contributivo lega l''assegno pensionistico ai contributi versati durante la vita lavorativa, non più (o non solo) all''ultimo stipendio. Carriere più frammentate, ingresso nel lavoro più tardivo e un''aspettativa di vita più lunga (che allunga il periodo su cui lo stesso montante contributivo viene diviso) contribuiscono a ridurre il tasso di sostituzione — la percentuale dell''ultimo stipendio che la pensione pubblica coprirà davvero.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quanto serve accumulare</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non esiste un numero universale: dipende da quanto vuoi vivere una volta smesso di lavorare, da quanti anni mancano alla pensione pubblica e da quanto già versato in forme integrative (fondo pensione negoziale, PIP, o investimenti personali dedicati a questo scopo). Quello che conta davvero è iniziare presto: per l''effetto dell''interesse composto, versare la stessa cifra a 30 anni invece che a 45 può tradursi in un capitale finale molto più alto, a parità di sforzo mensile.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Fondo pensione o investimento autonomo?</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un fondo pensione negoziale ha spesso il vantaggio del contributo aggiuntivo del datore di lavoro (se previsto dal CCNL) e di un trattamento fiscale agevolato sui versamenti — un vantaggio difficile da eguagliare con un investimento autonomo equivalente. Il rovescio della medaglia è una minore flessibilità: il capitale resta vincolato fino alla pensione, salvo casi specifici di anticipazione.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Simula il tuo scenario</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con il <a href="/calcolatore-pensione.php" class="text-accent hover:underline font-medium">calcolatore per la pensione</a> puoi stimare quanto capitale potresti accumulare entro l''età obiettivo, con un grafico anno per anno di come cresce versando una cifra fissa nel tempo — lo stesso principio dietro un <a href="/news/pac-piano-accumulo-etf-come-funziona" class="text-accent hover:underline font-medium">PAC</a>, applicato a un orizzonte di decenni invece che di pochi anni.</p>',
    'pubblicato',
    '2026-07-24 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'rendimento-totale-vs-cagr-come-leggere-la-performance',
    'Rendimento totale o CAGR: come leggere davvero la performance di un investimento',
    'Perché il rendimento totale da solo non basta a confrontare due investimenti, e cos''è il CAGR (tasso di crescita annuo composto) che risolve il problema.',
    'Differenza tra rendimento totale e CAGR (tasso di crescita annuo composto): come confrontare correttamente investimenti con orizzonti temporali diversi.',
    'investimenti',
    '📊',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Due investimenti possono avere lo stesso rendimento percentuale e raccontare storie completamente diverse, se non guardi anche a <strong>come</strong> quel rendimento è arrivato. Il rendimento totale da solo non basta a giudicare un investimento.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Rendimento totale vs rendimento annualizzato (CAGR)</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se un investimento passa da 10.000&euro; a 15.000&euro; in 5 anni, il <strong>rendimento totale</strong> è del 50%. Ma questo numero da solo non è confrontabile con un altro investimento durato un periodo diverso. Il <strong>CAGR</strong> (tasso di crescita annuo composto) risolve il problema: nello stesso esempio, corrisponde a circa l''8,4% annuo — il numero giusto per confrontare investimenti con orizzonti temporali diversi.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché due strumenti con lo stesso CAGR non sono equivalenti</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un CAGR dell''8% ottenuto con un percorso quasi lineare e uno ottenuto con un crollo del 40% seguito da un forte rimbalzo hanno lo stesso numero finale ma un profilo di rischio molto diverso — e, soprattutto, richiedono una tenuta psicologica molto diversa da parte di chi ci ha investito i propri risparmi. La <strong>volatilità</strong> del percorso conta quanto il risultato finale.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Il costo reale di una perdita: perché non è simmetrico</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un dettaglio spesso sottovalutato: un calo del 20% richiede un guadagno del 25% (non del 20%) solo per tornare al punto di partenza — e un calo del 50% richiede addirittura un +100%. <a href="/news/recupero-perdite-perche-non-e-simmetrico" class="text-accent hover:underline font-medium">Lo spieghiamo nel dettaglio in questo articolo</a>, perché è uno dei motivi principali per cui evitare grandi perdite conta più di massimizzare i guadagni nei periodi buoni.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Calcola il rendimento reale di un tuo investimento</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con il <a href="/calcolatore-rendimento.php" class="text-accent hover:underline font-medium">calcolatore di rendimento (ROI)</a> ottieni sia il totale che il CAGR. <a href="/investimenti.php" class="text-accent hover:underline font-medium">Su Reflexi</a>, ogni strumento nel tuo portafoglio mostra il rendimento reale calcolato sul costo medio di carico effettivo, non su una stima approssimativa.</p>',
    'pubblicato',
    '2026-07-27 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'recupero-perdite-perche-non-e-simmetrico',
    'Recupero perdite: perché un -20% richiede più di un +20% per tornare in pari',
    'L''asimmetria matematica tra perdite e guadagni necessari per recuperarle, e perché è uno degli argomenti più solidi a favore della diversificazione.',
    'Perché recuperare una perdita richiede un guadagno percentuale più alto della perdita stessa, spiegato con la matematica e il rischio di portafoglio.',
    'investimenti',
    '🩹',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Una delle asimmetrie meno intuitive della matematica finanziaria: se il tuo portafoglio perde il 20%, non basta un guadagno del 20% per tornare al punto di partenza. Serve di più. Molto di più se la perdita è grande.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché non è simmetrico</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un capitale di 10.000&euro; che scende del 20% diventa 8.000&euro;. Per tornare a 10.000&euro; da 8.000&euro;, serve un guadagno del <strong>25%</strong>, non del 20% — perché il 20% di recupero si calcola su una base già più piccola. Con perdite più grandi il divario si allarga rapidamente:</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li>Perdita del 10% &rarr; serve un guadagno dell''11,1% per recuperare</li><li>Perdita del 20% &rarr; serve un guadagno del 25%</li><li>Perdita del 33% &rarr; serve un guadagno del 50%</li><li>Perdita del 50% &rarr; serve un guadagno del 100%</li><li>Perdita del 75% &rarr; serve un guadagno del 300%</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché conta più di quanto sembri</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Questa asimmetria è uno degli argomenti più solidi a favore della <strong>diversificazione</strong> e contro il concentrare capitale in pochi strumenti ad alto rischio: non è solo una questione di “evitare l''ansia”, è matematica pura. Evitare un crollo del 50% è più efficace, sul lungo periodo, che inseguire un rendimento più alto nei periodi favorevoli — perché il costo di recupero da una grande perdita è sproporzionatamente alto.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Cosa significa in pratica</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non significa evitare il rischio del tutto (senza rischio, in genere, non c''è nemmeno rendimento reale sopra l''inflazione — <a href="/news/inflazione-potere-acquisto-perche-il-capitale-deve-crescere" class="text-accent hover:underline font-medium">ne parliamo qui</a>), significa dimensionare il rischio in modo che una perdita, quando arriva (e prima o poi arriva), resti recuperabile in un tempo ragionevole, non richieda un decennio di guadagni straordinari.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Fai il calcolo sul tuo caso</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il <a href="/calcolatore-recupero-perdite.php" class="text-accent hover:underline font-medium">calcolatore di recupero perdite</a> mostra esattamente il guadagno necessario per tornare in pari dopo un calo specifico — utile per capire in anticipo cosa comporta davvero un certo livello di rischio sul tuo portafoglio.</p>',
    'pubblicato',
    '2026-07-30 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'diversificazione-portafoglio-cosa-significa-davvero',
    'Diversificazione del portafoglio: cosa significa davvero (e cosa non lo è)',
    'Avere tanti titoli non è diversificazione se sono tutti correlati tra loro. Cosa significa diversificare davvero e quale prezzo comporta.',
    'Cosa significa davvero diversificare un portafoglio di investimenti, perché tanti titoli correlati non bastano, e il ruolo degli ETF globali ed elei PAC.',
    'investimenti',
    '🧺',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">“Non mettere tutte le uova nello stesso paniere” è probabilmente il consiglio finanziario più ripetuto e più frainteso: diversificare non significa comprare tante cose a caso, significa combinare strumenti che non si muovono tutti nella stessa direzione nello stesso momento.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cosa diversifica davvero</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Avere 15 azioni tecnologiche americane non è diversificazione reale: sono 15 scommesse molto correlate tra loro, che tendono a salire e scendere insieme. Diversificazione reale significa combinare asset class, aree geografiche e settori che reagiscono diversamente agli stessi eventi economici — un modo semplice ed efficiente per farlo, per chi non vuole selezionare titoli singoli, è un ETF ampiamente diversificato che replica un intero mercato globale.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Il prezzo della diversificazione</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Diversificare riduce la volatilità e il rischio di un crollo specifico, ma ha un costo: rinunci alla possibilità (rara, e quasi impossibile da prevedere in anticipo) di avere indovinato il singolo titolo che decuplica di valore. È uno scambio deliberato — meno rischio di rovina in cambio di meno possibilità di un exploit isolato — non un compromesso al ribasso.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Diversificazione nel tempo, non solo tra strumenti</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">C''è anche una diversificazione “temporale”: investire gradualmente nel tempo invece che tutto insieme in un solo momento (il principio dietro un <a href="/news/pac-piano-accumulo-etf-come-funziona" class="text-accent hover:underline font-medium">PAC</a>) riduce il rischio di aver investito tutto proprio nel punto sbagliato del mercato.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Guarda il tuo portafoglio nel suo insieme</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700"><a href="/investimenti.php" class="text-accent hover:underline font-medium">Su Reflexi</a> vedi tutti i tuoi strumenti — ETF, azioni, crypto — in un unico portafoglio, con il grafico storico che mostra come si muove l''insieme, non solo il singolo titolo: è proprio guardando l''insieme che si capisce se si è davvero diversificati o solo sparsi su tante posizioni correlate.</p>',
    'pubblicato',
    '2026-08-02 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'fondo-di-emergenza-quanto-tenere-da-parte',
    'Fondo di emergenza: quanto tenere da parte prima di iniziare a investire',
    'Perché costruire una riserva liquida di 3-6 mesi di spese essenziali dovrebbe venire prima di ogni investimento, non dopo.',
    'Quanto tenere in un fondo di emergenza (3-6 mesi di spese essenziali), perché deve restare liquido e perché viene prima degli investimenti.',
    'budget',
    '🛡️',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Prima di investire un solo euro, quasi tutti i consulenti finanziari concordano su un passo precedente: costruire un <strong>fondo di emergenza</strong> — una riserva di liquidità pronta all''uso, separata dagli investimenti, per gli imprevisti che prima o poi capitano a tutti.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quanto tenere da parte</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La regola più diffusa è coprire <strong>da 3 a 6 mesi</strong> di spese essenziali (non di reddito lordo: le spese reali che dovresti comunque sostenere — affitto o mutuo, bollette, spesa, trasporti). Chi ha un lavoro molto stabile o un doppio reddito familiare può stare più vicino a 3 mesi; chi ha un reddito irregolare (freelance, partita IVA) o è l''unico reddito della famiglia dovrebbe orientarsi verso 6 mesi o anche di più.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché deve restare liquido, non investito</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il fondo di emergenza non serve a rendere: serve a essere disponibile <strong>subito</strong>, senza dover vendere in perdita un investimento nel momento sbagliato solo perché è arrivata una spesa imprevista. Per questo va tenuto su un conto corrente o deposito facilmente svincolabile, non su un ETF che potrebbe essere temporaneamente in ribasso proprio quando serve prelevare.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">L''ordine giusto: prima il fondo, poi gli investimenti seri</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Senza un fondo di emergenza, un imprevisto (un guasto all''auto, una spesa medica) rischia di costringerti a vendere investimenti in un momento di mercato sfavorevole, o peggio, a indebitarti con una carta di credito revolving. Costruire prima il fondo, anche a costo di rimandare di qualche mese l''inizio degli investimenti, evita di dover smontare un piano a lungo termine per un problema di breve termine.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Costruiscilo con un obiettivo dedicato</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700"><a href="/budget.php" class="text-accent hover:underline font-medium">Su Reflexi</a> puoi impostare un obiettivo di risparmio dedicato al fondo di emergenza, separato dagli altri conti, e vedere il progresso reale mese per mese man mano che versi — lo stesso <a href="/calcolatore-obiettivo-risparmio.php" class="text-accent hover:underline font-medium">calcolatore di obiettivo di risparmio</a> ti dice quanto versare al mese per raggiungerlo entro una data che ti sei posto.</p>',
    'pubblicato',
    '2026-08-06 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'abbonamenti-dimenticati-come-scovare-spese-ricorrenti',
    'Abbonamenti dimenticati: come scovare le spese ricorrenti che erodono il budget',
    'Una persona su tre paga almeno un abbonamento che ha dimenticato di avere. Come scovarli sistematicamente e perché serve un controllo continuo, non una tantum.',
    'Come individuare abbonamenti e spese ricorrenti dimenticate che erodono il budget mensile senza che te ne accorga, e perché serve un controllo automatico.',
    'budget',
    '🔍',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Uno studio ricorrente nel settore fintech stima che una persona su tre paghi almeno un abbonamento che ha completamente dimenticato di avere. Non per disattenzione grave: semplicemente, un addebito ricorrente di pochi euro al mese è facile da perdere di vista in mezzo a decine di altre transazioni.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché sono difficili da notare</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un abbonamento da 60&euro; all''anno pesa poco su un singolo estratto conto mensile (5&euro;), ma sommato ad altri 4 o 5 abbonamenti dimenticati diventa una cifra non trascurabile nel corso di un anno — ed è proprio la piccola entità di ogni singolo addebito a renderlo invisibile mese dopo mese.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come scovarli sistematicamente</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Guarda 2-3 mesi di estratto conto di fila</strong>, non solo l''ultimo — un pattern ricorrente emerge solo nel confronto.</li><li><strong>Cerca importi identici a intervalli regolari</strong> — mensili o annuali, spesso con nomi di servizi poco riconoscibili sull''estratto conto.</li><li><strong>Controlla gli addebiti annuali</strong>, non solo quelli mensili — sono i più facili da dimenticare perché capitano una sola volta l''anno.</li></ul><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Un controllo automatico, non solo una tantum</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il problema di un controllo manuale è che va ripetuto: un nuovo abbonamento dimenticato può comparire in qualsiasi momento (un trial gratuito diventato a pagamento, un rinnovo automatico non cancellato in tempo). Serve un controllo continuo, non un''unica verifica annuale.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Rilevamento automatico</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700"><a href="/budget.php" class="text-accent hover:underline font-medium">Reflexi</a> analizza le tue transazioni cercando pattern di spesa che si ripetono a intervalli regolari ma non sono dichiarati come ricorrenti nell''app — capita spesso di scoprire un rinnovo dimenticato che altrimenti sarebbe passato inosservato per mesi. Dalla sezione Abbonamenti basta premere “Dichiara” sul pattern rilevato per tenerlo sotto controllo da quel momento in poi.</p>',
    'pubblicato',
    '2026-08-09 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'mutuo-tasso-fisso-o-variabile-come-scegliere',
    'Mutuo a tasso fisso o variabile: come scegliere',
    'Il tasso fisso costa un premio per la certezza, il variabile parte più basso ma il rischio è tuo. Cosa considerare per scegliere in base alla tua situazione.',
    'Differenze tra mutuo a tasso fisso e variabile: vantaggi, rischi e cosa considerare (durata, margine di bilancio) per scegliere quello giusto per te.',
    'mutui',
    '⚖️',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Tasso fisso o tasso variabile è probabilmente la prima grande decisione da prendere quando si accende un mutuo, ed è anche quella su cui circolano più semplificazioni. Non esiste una risposta valida per tutti: dipende da tolleranza al rischio, durata del mutuo e condizioni di mercato al momento della scelta.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Tasso fisso: certezza, a un prezzo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con il tasso fisso, la rata resta identica per tutta la durata del mutuo, indipendentemente da come si muovono i tassi di mercato nel frattempo. Il vantaggio è la <strong>prevedibilità totale</strong>: sai esattamente cosa pagherai tra 10 o 20 anni. Lo svantaggio è che, storicamente, il tasso fisso di partenza è quasi sempre più alto del tasso variabile di partenza — paghi un premio per la certezza.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Tasso variabile: parti più basso, ma il rischio è tuo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il tasso variabile è agganciato a un indice di riferimento (tipicamente l''Euribor) e si aggiorna periodicamente: la rata può scendere se i tassi calano, ma può anche salire, a volte in modo significativo, se i tassi di mercato aumentano. Chi lo sceglie accetta questa incertezza in cambio di un punto di partenza solitamente più conveniente.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Cosa considerare per scegliere</h3><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Durata residua</strong> — un mutuo breve (10 anni) espone meno all''incertezza di lungo periodo rispetto a uno da 30 anni.</li><li><strong>Margine di bilancio</strong> — se un aumento di rata del 20-30% metterebbe in difficoltà il bilancio familiare, la certezza del fisso vale probabilmente il premio pagato.</li><li><strong>Fase del ciclo dei tassi</strong> — il divario tra fisso e variabile si allarga o si stringe in base alle aspettative di mercato sui tassi futuri, che cambiano nel tempo.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Un''opzione intermedia: il tasso misto o variabile con cap</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Alcuni istituti offrono varianti intermedie (tasso variabile con un tetto massimo, o la possibilità di passare da variabile a fisso durante la vita del mutuo) che riducono il rischio estremo mantenendo un punto di partenza più basso — vale la pena informarsi anche su queste opzioni, non solo sulle due estreme.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Segui il tuo mutuo, qualunque tasso tu scelga</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700"><a href="/mutui.php" class="text-accent hover:underline font-medium">Reflexi</a> supporta sia mutui a tasso fisso che variabile, con lo storico delle variazioni di tasso per quelli variabili, così il piano di ammortamento resta sempre accurato anche quando la rata cambia nel tempo.</p>',
    'pubblicato',
    '2026-08-12 09:00:00'
);

